mapper.select:
SELECT ch.*, u.user_name AS operator_name, c.car_number, g.gate_name FROM car_history ch LEFT JOIN user u ON ch.car_history_operator_id = u.id LEFT JOIN car c ON ch.car_id = c.id LEFT JOIN gate g ON ch.gate_id = g.id
AND c.car_number LIKE CONCAT('%', #{carNumber}, '%')
AND ch.gate_id = #{gateId}
AND ch.car_history_type = #{carHistoryType}
AND ch.car_history_time BETWEEN #{rangeStart} AND #{rangeEnd}
ORDER BY ch.id ASC
